/**
 * Triggers a file download from in-memory data.
 *
 * The anchor has to be attached to the document before it is clicked — Firefox
 * ignores clicks on detached anchors entirely, and Chromium's download path is
 * unreliable for them. Found by an E2E test that never saw the download event.
 */
export function downloadJson(filename: string, data: unknown): void {
  const url = URL.createObjectURL(
    new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }),
  )
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.style.display = 'none'
  document.body.appendChild(a)
  a.click()
  a.remove()
  // Revoke on the next tick; revoking synchronously can cancel the download.
  setTimeout(() => URL.revokeObjectURL(url), 0)
}
